INSERT IGNORE INTO `settings` (`key`, `value`) VALUES ('contact', '{\"kicker\":\"Let\'s Collaborate\",\"heading\":\"Punya event yang ingin diwujudkan?\",\"description\":\"Diskusikan kebutuhan acara, scope pekerjaan, timeline, dan kebutuhan teknis bersama tim CV AMANA PERKASA.\",\"phone\":\"08xx-xxxx-xxxx\",\"email\":\"email@perusahaan.com\",\"address\":\"Alamat perusahaan dapat diganti melalui panel admin.\",\"instagram\":\"@amanaperkasa\",\"whatsapp\":\"\"}');
